text:
**バックエンド**(state の保存先の設定)を S3 にするのが実務の定番です。典型例を読んでみます。

```hcl
terraform {
  backend "s3" {
    bucket         = "skillax-tfstate"
    key            = "prod/network/terraform.tfstate"
    region         = "ap-northeast-1"
    dynamodb_table = "tfstate-lock"
  }
}
```

`bucket` は保存先バケット、`key` はバケット内のパスです。key は「環境/コンポーネント」で切る命名が多く、ここを見るとその構成がどの単位で分割されているかが分かります。`dynamodb_table` は**ロック**(同時 apply による state 破損を防ぐ排他制御)用のテーブルです。🟡 backend を見たら「どこに・どのパスで・ロックは何か」の3点を読み取りましょう。

sample:
# backend "s3" の key は「環境/コンポーネント」でパスを切る流儀が定番です。
# ここでは key の組み立てロジックだけを locals で再現します。
variable "env" {
  default = "stg"
}

variable "component" {
  default = "app"
}

locals {
  # 例: stg/app/terraform.tfstate
  state_key = "${var.env}/${var.component}/terraform.tfstate"
}

output "state_key" {
  value = local.state_key
}

exercise.starter:
variable "project" {
  default = "skillax"
}

# env / component の variable と output を書く

exercise.answer:
# backend の bucket / key は直書きされていることが多いですが、
# 命名規則としては「project-tfstate」「env/component/terraform.tfstate」の
# 組み立てです。この規則が読めると state の置き場所を推測できます。
variable "project" {
  default = "skillax"
}

variable "env" {
  default = "prod"
}

variable "component" {
  default = "network"
}

output "bucket" {
  value = "${var.project}-tfstate"
}

output "state_key" {
  value = "${var.env}/${var.component}/terraform.tfstate"
}
